                    } catch (Exception ignore) {
                        // 忽略无法加载的注释文件，尽力而为
                    }
                }
                return res;
            } finally {
                rl.restore();
            }
        } catch (DocumentException | FileNotFoundException e) {
            throw new RuntimeException("OFD解析失败，原因:" + e.getMessage(), e);
