     * 获取 解密入口文件
     * <p>
     * 如果文件不存在那么创建新的文件
     *
     * @return 解密入口文件
     */
    public Encryptions obtainEncryptions() {
        Encryptions encryptions = null;
        try {
            encryptions = this.getEncryptions();
        } catch (DocumentException e) {
            throw new RuntimeException("无法解析解密入口文件", e);
        }
        if (encryptions == null) {
            encryptions = new Encryptions();
            // 添加到OFD容器内
