        final int numberOfPages = getNumberOfPages();
        List<PageInfo> res = new ArrayList<>(numberOfPages);
        for (int i = 0; i < numberOfPages; i++) {
            PageInfo pageInfo = getPageInfo(i + 1);
            res.add(pageInfo);
        }
        return res;
    }

