/**
     * 转换 CMYK为RGB
     *
     * @param c 青色
     * @param m 洋红色
     * @param y 黄色
     * @param k 黑色
     * @return RGB颜色值
     */
public static int[] cmykToRgb(int c, int m, int y, int k) {
        c = Math.min(c, 100);
        c = Math.max(c, 0);

        m = Math.min(m, 100);
        m = Math.max(m, 0);

        y = Math.min(y, 100);
        y = Math.max(y, 0);

        k = Math.min(k, 100);
        k = Math.max(k, 0);

        int r = 255 * (1 - c / 100) * (1 - k / 100);
        int g = 255 * (1 - m / 100) * (1 - k / 100);
        int b = 255 * (1 - y / 100) * (1 - k / 100);
        return new int[]{r, g, b};
    }

