     */
public TrueTypeFont getFontAtIndex(int idx) throws IOException {
        if (idx < 0 || idx >= numFonts) {
            throw new IllegalArgumentException("索引号 不存在"+ idx);
        }
        stream.seek(fontOffsets[idx]);
        return new TrueTypeFont().parse(stream);
    }

