     * <p>
     * 长度不足将会自动填充空白字符，长度不足则截取
     *
     * @param expectCount 期待长度
     * @return 字符串数组
     */
    public String[] expectStrArr(int expectCount) {
        String[] res = new String[expectCount];
        for (int i = 0; i < expectCount; i++) {
            if (i < array.size()) {
                res[i] = (array.get(i));
            } else {
                res[i] = "";
            }
        }
        return res;
    }

    /**
     * 获取浮点数组
     *
     * @return 浮点数组
     */
    public Double[] toDouble() {
        return this.array.stream()
                .map(STBase::toDouble)
                .toArray(Double[]::new);
    }

    /**
     * 获取整形数组
     *
     * @return 整形数组
     */
    public Integer[] toInt() {
        return this.array.stream()
                .map(STBase::toInt)
                .toArray(Integer[]::new);
    }


    public ST_Array setArray(List<String> array) {
        this.array = array;
        return this;
    }

    /**
     * 数组长度
     *
     * @return 数组长度
     */
    public int size() {
        return this.array.size();
    }

    /**
     * 反序列化为矩阵数组
     *
     * @return 矩阵
     */
    public double[][] toMtx() {
        if (size() != 6) {
            throw new IllegalArgumentException("矩阵数组必须有 9个元素");
        }

        double[][] mtx = new double[3][3];
        mtx[0][0] = Double.parseDouble(array.get(0));
        mtx[0][1] = Double.parseDouble(array.get(1));
        mtx[0][2] = 0;

        mtx[1][0] = Double.parseDouble(array.get(2));
        mtx[1][1] = Double.parseDouble(array.get(3));
        mtx[1][2] = 0;

        mtx[2][0] = Double.parseDouble(array.get(4));
        mtx[2][1] = Double.parseDouble(array.get(5));
        mtx[2][2] = 1;

        return mtx;
    }

    public void printMtx() {
        double[][] m = toMtx();
        for (double[] doubles : m) {
            for (double aDouble : doubles) {
                System.out.print(fmt(aDouble) + "\t");
            }
            System.out.println();
        }
    }

    /**
     * 获取Index上的数字
     * <p>
     * 注意数组越位
     *
     * @param index index
     * @return 数字
     */
    public Double get(int index) {
        final String s = array.get(index);
        return Double.parseDouble(s);
    }

    /**
     * 获取Index上的数字
     * <p>
     * 注意数组越位
     *
     * @param index index
     * @return 数字
     */
    public Integer getInt(int index) {
        final String s = array.get(index);
        if (s.startsWith("#")) {
            // 16进制数字
            return Integer.parseInt(s.substring(1), 16);
        } else {
            return Integer.parseInt(s);
        }
    }

    /**
     * 获取期待长度的数组
     * <p>
     * 如果无法解析或长度不足则补充0
     *
     * @param len 长度
     * @return 数组
     */
    public int[] expectIntArr(int len) {
        int[] res = new int[len];
        for (int i = 0; i < len; i++) {
            if (i >= array.size()) {
                // 防止越界
                break;
            }
            try {
                res[i] = getInt(i);
            } catch (NumberFormatException | IndexOutOfBoundsException e) {
                res[i] = 0;
            }
        }
        return res;

    }

    /**
     * 获取期待长度的数组
     * <p>
     * 如果无法解析或长度不足则补充0
     *
     * @param len 长度
     * @return 数组
     */
    public double[] expectArr(int len) {
        double[] res = new double[len];
        for (int i = 0; i < len; i++) {
            if (i >= array.size()) {
                // 防止越界
                break;
            }
            try {
                res[i] = get(i);
            } catch (NumberFormatException e) {
                res[i] = 0;
            }
        }
        return res;
    }

    @Override
    public ST_Array clone() {
        ST_Array res = new ST_Array();
        for (String item : this.array) {
            res.add(item);
        }
        return res;
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        for (String item : array) {
            sb.append(' ').append(item);
        }
        return sb.toString().trim();
    }

    @Override
    public boolean equals(Object obj) {
        if (obj == this) {
            return true;
        }
        if (!(obj instanceof ST_Array)) {
            return false;
        }
        ST_Array that = (ST_Array) obj;
        return that.array.equals(this.array);
    }
}

