/**
     * 内容分割调整
     * <p>
     * 根据分割高度调整两个克隆元素，达成分割元素的效果
     *
     * @param <T>     Div子类泛型参数
     * @param sHeight 分割内容的高度
     * @param div1    克隆元素1
     * @param div2    克隆元素2
     * @return 分割调整后的两个Div
     */
public <T extends Div> Div[] contentSplitAdjust(double sHeight, T div1, T div2) {
        /*
         * 调整边框等配置
         * div1 无下边，总高度为切分高度
         * div2 无上边，高度为剩余高度
         */
        // 减去顶边的布局区域
        double h1 = sHeight - (div1.getMarginTop() + div1.getBorderTop() + div1.getPaddingTop());
        div1.setHeight(h1)
                // 取消低边的所有布局
                .setMarginBottom(0d)
                .setBorderBottom(0d)
                .setPaddingBottom(0d);

        // 减去截断内容
        double h2 = div2.getHeight() - h1;
        div2.setHeight(h2)
                // 取消顶边的所有布局
                .setMarginTop(0d)
                .setBorderTop(0d)
                .setPaddingTop(0d);
        return new Div[]{div1, div2};
    }

