/**
     * 创建新的行
     *
     * @param width 行宽度
     * @return 行块
     */
private TxtLineBlock newLine(double width) {
        return new TxtLineBlock(width, lineSpace, textAlign);
    }

/**
     * 处理Span内部含有换行符转换为占满剩余行空间的多个元素队列
     *
     * @param seq 待处理Span队列
     * @return 处理后含有占满剩余行空间的Span队列
     */
private LinkedList<Span> spanLinebreakSplit(LinkedList<Span> seq) {
        LinkedList<Span> sps = new LinkedList<>();
        if (seq == null || seq.isEmpty()) {
            return sps;
        }
        while (!seq.isEmpty()) {
            Span pop = seq.pop();
            // 通过换行符对span内容进行分割，获取新的队列
            LinkedList<Span> spans = pop.splitLineBreak();
            sps.addAll(spans);
        }
        return sps;
    }

/**
     * 处理占位符
     *
     * @param seq 段落中的span队列
     */
private void processPlaceholder(LinkedList<Span> seq) {
        if (seq == null || seq.isEmpty()) {
            return;
        }
        // 不需要加入占位符
        if ((firstLineIndent == null || firstLineIndent == 0)
                && (firstLineIndentWidth == null || firstLineIndentWidth == 0)) {
            return;
        }

        Span firstSpan = seq.peek();
        if (firstSpan instanceof PlaceholderSpan) {
            PlaceholderSpan h = (PlaceholderSpan) firstSpan;
            // 已经存在段落缩进并且设置的段落缩进为0，那么删除该占位符
            if (h.getHoldWidth() == 0 && h.getHoldNum() == 0) {
                seq.pop();
            }
            if (firstLineIndentWidth != null && firstLineIndentWidth > 0) {
                h.setHoldWidth(firstLineIndentWidth);
            } else {
                // 重设占位符的宽度
                h.setHoldChars(firstLineIndent);
            }
            return;
        }

        if (firstLineIndentWidth != null) {
            // 使用指定宽度和高度的占位符
            seq.push(new PlaceholderSpan(firstLineIndentWidth, firstSpan.getFontSize()));
        } else {
            // 如果第一个不是占位符，并且占位符数目大于0 那么创建新的占位符,并且加入渲染队列
            seq.push(new PlaceholderSpan(firstLineIndent, firstSpan));
        }
    }

/**
     * 如果元素高度不存在那么设置高度
     * <p>
     * 如果已经设置了高度，该方法不会对该高度造成影响
     *
     * @param height 高度
     */
private void setHeightIfNotExist(double height) {
        if (getHeight() == null || getHeight() == 0) {
            setHeight(height);
        }
    }

/**
     * 元素是否可以拆分
     * <p>
     * 特殊的：
     * 如果没有或只有一个文字，那么无论如何设置integrity都为不可拆分
     *
     * @return true 可以拆分；false 不能拆分
     */
public Boolean isIntegrity() {
        if (text == null || text.length() <= 1) {
            integrity = true;
        }
        return integrity;
    }

/**
     * 获取字体图形列表
     *
     * @return 字体图形列表
     */
public List<TxtGlyph> glyphList() {
        if (txtGlyphsCache == null) {
            txtGlyphsCache = new LinkedList<>();
            for (char c : this.text.toCharArray()) {
                txtGlyphsCache.add(new TxtGlyph(c, this));
            }
        }
        return txtGlyphsCache;
    }

/**
     * @return 不拆分情况下都放在一行内占用的大小
     */
public Rectangle blockSize() {
        List<TxtGlyph> txtGlyphs = glyphList();
        double width = 0;
        double height = 0;
        for (TxtGlyph glyph : txtGlyphs) {
            width += glyph.getW();
            if (glyph.getH() > height) {
                height = glyph.getH();
            }
        }
        return new Rectangle(width, height);
    }

/**
     * 是否是一个占满剩余行空间的Span
     *
     * @return true 标识span会占满剩余的行空间； false 不占满
     */
public boolean hasLinebreak() {
        return linebreak;
    }

/**
     * 尝试向行中加入文字单元
     *
     * @param span 文字单元
     * @return true - 足够容纳可以加入；false - 无法容纳无法加入
     */
public boolean tryAdd(Span span) {
        Rectangle rec = span.blockSize();
        if (rec.getWidth() + width > lineMaxAvailableWidth) {
            // 空间不足不足以容纳元素
            return false;
        }
        width += rec.getWidth();
        if (rec.getHeight() > maxSpanHeight) {
            // 判断行高
            maxSpanHeight = rec.getHeight();
        }
        inlineSpans.add(span);
        return true;
    }

/**
     * 尝试通过切分文字单元的方式加入行内
     * <p>
     * 如果文字单元能够被切分，那么会返回切分后剩余部分文字单元
     * <p>
     * 如果切分之后也无法加入行中，那么返回空。
     *
     * @param span 待切分文字单元
     * @return null 表示行的空间耗尽，无法加入新的文字；切分后的剩余的文字单元
     */
public Span trySplitAdd(Span span) {
        if (span.isIntegrity()) {
            throw new IllegalStateException("文字单元（Span）不可拆分");
        }
        // 获取剩余宽度
        double remainWidth = lineMaxAvailableWidth - width;
        // 文字单元切分点
        int splitIndex = 0;
        // 行中的剩余空间不足且Span可以被换行等分割
        List<TxtGlyph> txtGlyphs = span.glyphList();
        for (int i = 0; i < txtGlyphs.size(); i++) {
            TxtGlyph txt = txtGlyphs.get(i);
            if (txt.getW() <= remainWidth) {
                remainWidth -= txt.getW();
                continue;
            }
            if (i == 0) {
                // 一个字符都无法加入到行内，说明行空间基本耗尽，需要换行
                return null;
            }
            // 找到前一个字符
            splitIndex = i;
            break;
        }
        // 切分文字单元
        Span[] split = span.split(splitIndex);
        // 前半段放入行中
        tryAdd(split[0]);
        // 后半段返回，准备加入下一段
        return split[1];
    }

public boolean isEmpty() {
        return inlineSpans.isEmpty();
    }

/**
     * 获取整个行占据的高度（文字高度 + 行间距）
     *
     * @return 行占据的高度
     */
public double getHeight() {
        return maxSpanHeight + lineSpace;
    }

