/**
     * 绘制水印
     *
     * @param ctx 绘制上下文
     * @throws IOException ignore
     */
@Override
    public void draw(DrawContext ctx) throws IOException {
        if (this.value == null || this.value.isEmpty()) {
            return;
        }
        if (this.annotation == null) {
            return;
        }
        if (extFontPath != null) {
            // 添加外部字体
            ctx.addFont(fontName, extFontPath);
        }

        ctx.fillStyle = this.color;
        ctx.font = getFont();
        if (this.letterSpacing != 0) {
            // 设置字间距
            ctx.getFont().setLetterSpacing(this.letterSpacing);
        }
        // 设置字体颜色
        if (this.color != null && !this.color.isEmpty()) {
            ctx.fillStyle = this.color;
        }

        double width = annotation.getBoundary().getWidth();
        double height = annotation.getBoundary().getHeight();

        /*
         * 计算水印实际占位横向宽度和竖向高度，并自适应计算水印的起始坐标.
         */
        TextMetrics metrics = ctx.measureText(this.value);

        double x = annotation.getBoundary().getTopLeftX();
        while (x < width) {
            double y = annotation.getBoundary().getTopLeftY();
            while (y < height) {
                ctx.save();
                ctx.setGlobalAlpha(this.globalAlpha);
                ctx.translate(x, y);
                ctx.rotate(this.angle);
                ctx.fillText(this.value, 0, metrics.fontSize);
                ctx.restore();
                if (isDEBUG()) {
                    debugBorder(ctx, metrics, x, y);
                }
                y += intervalY;
            }
            x += intervalX;
        }
    }

@Override
    public void draw(DrawContext ctx) throws IOException {
        // 添加外部字体
//        if (font != null && !StringUtils.isBlank(font.getName()) && font.getFontFile() != null) {
//            ctx.addFont(font.getName(), font.getFontFile());
//        }
        // 字体
        FontSetting fontSetting = new FontSetting(fontSize, font);
        fontSetting.setLetterSpacing(letterSpacing);
        if (bold) {
            fontSetting.setBold();
        }
        if (weight != null) {
            fontSetting.setFontWeight(weight.getWeight());
        }
        fontSetting.setItalic(italic);
        fontSetting.setTextAlign(textAlign);
        ctx.setFont(fontSetting);

        // 字体颜色
        ctx.setFillColor(color);
        /**
         *  a 水平缩放绘图 小于1-水平挤压，1-正常，大于1-水平拉伸，这是一个比例值，比如0.5表示字宽变为原来的50%
         *  b 水平倾斜绘图 文本区域的左边框固定，垂直方向移动右边框，正数-向下移动右边框，0-不倾斜，负数-向上移动右边框，视觉效果上文本会有轻微的垂直位移
         *  c 垂直倾斜绘图 文本区域的上边框固定，水平方向移动下边框，正数-向右移动下边框，0-不倾斜，负数-向左移动下边框，视觉效果上文本会有轻微的水平位移
         *  d 垂直缩放绘图 小于1-垂直挤压，1-正常，大于1-垂直拉伸，这是一个比例值，比如0.5表示字宽变为原来的50%
         *  e 水平移动绘图 水平偏移量，单位：毫米
         *  f 垂直移动绘图 垂直偏移量，单位：毫米
         */
        ctx.setTransform(horizontalScaling, verticalInclination, horizontalInclination, verticalScaling, offsetX, offsetY);
        // 计算文本宽度
        double textWidth = ctx.measureText(text).width;
        // 根据对齐方式计算绘制文本的起始位置
        double x = 0;
        if (textLayoutAlign != null) {
            switch (textLayoutAlign) {
                case left: {
                    x = 0;
                    break;
                }
                case right: {
                    x = getWidth() - textWidth;
                    break;
                }
                case center: {
                    x = (getWidth() - textWidth) / 2;
                    break;
                }
                default: {
                    x = 0;
                }
            }
        }
        ctx.fillText(text, x, fontSize);

        // 绘制下滑线
        if (underline) {
            ctx.setLineWidth(underlineWidth == 0D ? fontSize * 0.05 : underlineWidth);
            ctx.beginPath();
            ctx.setGlobalAlpha(1D);
            ctx.strokeStyle = CT_Color.rgb(color);
            ctx.moveTo(x, fontSize + offsetY + underlineOffset);
            ctx.lineTo(x + textWidth, fontSize + offsetY + underlineOffset);
            ctx.stroke();
        }
    }

/**
     * 单元格文字内容绘制
     *
     * @param ctx 绘制上下文
     * @throws IOException 文字绘制异常
     */
private void drawText(DrawContext ctx) throws IOException {
        if (this.value == null || this.value.isEmpty()) {
            return;
        }

        // 设置字体样式
        String fontStr = "";
        if (italic) {
            fontStr += "italic ";
        }
        if (bold) {
            fontStr += "bold ";
        } else if (fontWeight != null && !fontWeight.isEmpty()) {
            fontStr += fontWeight + " ";
        }
        ctx.font = fontStr + STBase.fmt(fontSize) + "mm " + fontName;
        if (this.letterSpacing != 0) {
            // 设置字间距
            ctx.getFont().setLetterSpacing(this.letterSpacing);
        }

        // 设置字体颜色
        if (this.color != null && !this.color.isEmpty()) {
            ctx.fillStyle = this.color;
        }

        double width = canvas.getWidth();
        double height = canvas.getHeight();
        TextMetrics textMetrics = ctx.measureText(this.value);


        LinkedList<TextLine> lines = new LinkedList<>();
        double textLineWidth = 0;
        int offset = 0;
        // 分段
        for (int i = 0; i < this.value.length(); i++) {
            char c = this.value.charAt(i);
            // 换行符提前结束
            if (c == '\n') {
                lines.add(new TextLine(this.value.substring(offset, i), textLineWidth));
                offset = i + 1;
                textLineWidth = 0;
                continue;
            }
            double cWidth = 0;
            if (i == this.value.length() - 1) {
                cWidth = ctx.measureText(String.valueOf(c)).width;
            } else {
                cWidth = textMetrics.offset[i];
            }
            if (textLineWidth + cWidth > width) {
                // 超出宽度，换行
                lines.add(new TextLine(this.value.substring(offset, i), textLineWidth));
                offset = i;
                textLineWidth = cWidth;
            } else {
                textLineWidth += cWidth;
            }
        }
        // 最后一行
        if (offset < this.value.length()) {
            lines.add(new TextLine(this.value.substring(offset), textLineWidth));
        }


        // 内容高度：(字号 + 行间距) *行数
        double contentHeight = (this.fontSize + this.lineSpace) * lines.size();

        double offsetY = 0;
        // 第一行 Y 偏移量计算：字体坐标位于字体的左下角
        if (this.verticalAlign == VerticalAlign.top) {
            offsetY = fontSize;
        } else if (this.verticalAlign == VerticalAlign.center) {
            offsetY = height / 2 - contentHeight / 2 + fontSize;
        } else {
            // 底部对齐 偏移量为：总高度 - 内容高度 + 字号
            offsetY = height - contentHeight + fontSize;
        }

        for (TextLine line : lines) {
            double offsetX = 0;
            // 按照左右浮动方式 依次计算出每行的X 偏移量
            if (this.textAlign == TextAlign.left || this.textAlign == TextAlign.start || this.textAlign == null) {
                // 左浮动
                offsetX = 0;
            } else if (this.textAlign == TextAlign.center) {
                // 居中
                offsetX = (width - line.width) / 2d;
            } else {
                // 右浮动
                offsetX = width - line.width;
            }
            if (!"".equals(line.text)) {
                ctx.fillText(line.text, offsetX, offsetY);
            }
            // 文字装饰线条宽度
            // 比例系数由经验指定无特定规则
            double fontLineWidth = fontSize / 30;
            double underlineOffset = fontLineWidth * 3.2;
            // 下划线
            if (this.underline) {
                ctx.save();
                ctx.setLineWidth(fontLineWidth);
                ctx.beginPath();
                ctx.moveTo(offsetX, offsetY + underlineOffset);
                ctx.lineTo(offsetX + line.width, offsetY + underlineOffset);
                ctx.stroke();
                ctx.restore();
            }
            // 删除线
            if (this.deleteLine) {
                ctx.save();
                ctx.setLineWidth(fontLineWidth);
                ctx.beginPath();
                // 由于文字定位在基线位置，此处以 5/18 比例计算出删除线位置，5/18为经验值，无特殊意义。
                ctx.moveTo(offsetX, offsetY - fontSize * 5 / 18);
                ctx.lineTo(offsetX + line.width, offsetY - fontSize * 5 / 18);
                ctx.stroke();
                ctx.restore();
            }

            if (DEBUG) {
                ctx.save();
                ctx.setLineDash(1.5d, 1.5d);
                ctx.setLineWidth(0.1);
                ctx.setGlobalAlpha(0.53);
                ctx.strokeStyle = "rgb(255,0,0)";
                ctx.strokeRect(offsetX, offsetY - fontSize, line.width, fontSize + lineSpace);
                ctx.stroke();
                ctx.restore();
            }
            // 绘制完上一行后将offsetY移动到下一行
            offsetY += this.fontSize + this.lineSpace;
        }

        if (DEBUG) {
            debugBorder(ctx);
        }
    }

