     * @param italic true - 斜体样式； false - 正常
     * @return this
     */
public CT_Text setItalic(Boolean italic) {
        if (italic == null) {
            this.removeAttr("Italic");
            return this;
        }
        this.addAttribute("Italic", italic.toString());
        return this;
    }

