     * 【必选】
     * 增加 文字内容
     * <p>
     * 也就是一段字符编码串
     * <p>
     * 如果字符编码不在XML编码方式的字符范围之内，应采用“\”加四位
     * 十六进制数的格式转义；文字内容中出现的空格也需要转义
     * 若 TextCode 作为占位符使用时一律采用  ¤ （\u00A4）占位
     *
     * @param textCode 文字内容
     * @return this
     */
public CT_Text addTextCode(TextCode textCode) {
        if (textCode == null) {
            return this;
        }
        this.add(textCode);
        return this;
    }

/**
     * 文本浮动带来的偏移量因子
     *
     * @param align         对齐方向
     * @param width         文本宽度
     * @param readDirection 阅读方向
     * @return 浮动因子
     */
private double textFloatFactor(TextAlign align, double width, int readDirection) {
        double factor = 0;
        switch (align) {
            case start:
            case left:
                factor = 0;
                break;
            case end:
            case right:
                factor = -width;
                break;
            case center:
                factor = -width / 2;
                break;
        }
        if (readDirection == 180 || readDirection == 270) {
            factor = -factor;
        }
        return factor;
    }

/**
     * 应用当前上下文中的绘制参数到绘制对象
     */
private void applyDrawParam(CT_GraphicUnit<?> p) {
        if (p == null) {
            return;
        }
        // 设置区域
        p.setBoundary(this.boundary.clone());

        // 设置透明度
        if (this.state.globalAlpha != null) {
            p.setAlpha((int) (255 * this.state.globalAlpha));
        }

        // 设置变换矩阵 忽略已经设置了变换矩阵的图元
        if (this.state.ctm != null && p.getCTM() == null) {
            p.setCTM(this.state.ctm.clone());
        }
        // 设置填充颜色
        CT_Color fillColor = detectColor(this.fillStyle);
        if (fillColor != null) {
            this.state.drawParam.setFillColor(fillColor);
        }
        // 设置描边颜色
        CT_Color strokeColor = detectColor(this.strokeStyle);
        if (strokeColor != null) {
            this.state.drawParam.setStrokeColor(strokeColor);
        }

        // 设置绘制参数
        ST_ID paramObjId = this.resManager.addDrawParam(this.state.drawParam);
        p.setDrawParam(paramObjId.ref());

        // 设置裁剪区域
        if (this.state.clipArea != null) {
            Clips clips = new Clips();
            org.ofdrw.core.pageDescription.clips.Area area = new org.ofdrw.core.pageDescription.clips.Area();
            CT_Path clipObj = new CT_Path().setAbbreviatedData(this.state.clipArea.clone());
            clipObj.setFill(true);
            // 裁剪区域与Canvas等大
            clipObj.setBoundary(new ST_Box(0, 0, this.boundary.getWidth(), boundary.getHeight()));
            if (this.state.ctm != null && !ONE.equals(this.state.ctm)) {
                // 由于图元内的裁剪区域受到图元的变换矩阵影响，
                // 而裁剪区域是位于未受到变换的原始画布上的区域，
                // 因此在图元内部的裁剪区为需要叠加一个图元内变换的逆变换，
                // 才可以实现向外部空间的映射。
                ST_Array inverse = inverse(this.state.ctm);
                if (inverse == null) {
                    // 获取获取可逆矩阵时放弃裁剪区
                    return;
                }
                clipObj.setCTM(inverse);
            }
            area.setClipObj(clipObj);
            clips.addClip(new CT_Clip().addArea(area));
            p.setClips(clips);
        }
    }

/**
     * 解析字体配置字符串为字体配置对象
     * <p>
     * 解析 font 字符串，格式为：[font-style] [font-weight] font-size font-family [] 表示可选
     * <p>
     * font-style: normal | italic
     * font-weight: normal | bold | bolder | lighter | 100 | 200 | 300 | 400 | 500 | 600 | 700 | 800 | 900
     * font-size: 12px | 3.17mm
     * font-family: 宋体 | SimSun | Times New Roman | Times | serif | sans-serif | monospace | cursive | fantasy
     * font-family 为必选项，其他为可选项
     * <p>
     * font-size 可以使用 px 或 mm 作为单位，若不指定单位则默认为 mm
     *
     * @param fontSettingStr 字体配置字符串
     * @param fs             字体配置对象
     * @return 若文档已经存在字体，那么返回它的字体对象，若不存咋那么只设置 FontSetting 并返还null
     */
private CT_Font fontStyleToSetting(String fontSettingStr, FontSetting fs) {
        if (fontSettingStr == null || fontSettingStr.isEmpty() || fs == null) {
            return null;
        }
        String[] arr = fontSettingStr.trim().split(" ");
        if (arr.length < 2) {
            return null;
        }

        /*
         * 设置 字体 名称
         */
        int off = arr.length - 1;
        String fontFamily = arr[off].trim();
        Font nameFont = new Font(fontFamily, fontFamily);

        CT_Font ctFont = null;
        ExistCTFont existCTFont = resManager.getFont(fontFamily);
        if (existCTFont != null) {
            ctFont = existCTFont.font;
            if (existCTFont.absPath != null) {
                nameFont = new Font(ctFont.getFontName(), ctFont.getFamilyName(), existCTFont.absPath);
            } else {
                nameFont = new Font(ctFont.getFontName(), ctFont.getFamilyName());
            }
        }
        fs.setFont(nameFont);

        /*
         * 设置 字号
         */
        off--;
        // 解析font-size 单位可能是 px 或 mm 或 空
        String fontSizeStr = arr[off].trim();
        double fontSize = 1;
        try {
            if (fontSizeStr.endsWith("px")) {
                fontSizeStr = fontSizeStr.substring(0, fontSizeStr.length() - 2).trim();
                fontSize = Double.parseDouble(fontSizeStr) / PPM;
            } else if (fontSizeStr.endsWith("mm")) {
                fontSizeStr = fontSizeStr.substring(0, fontSizeStr.length() - 2).trim();
                fontSize = Double.parseDouble(fontSizeStr);
            } else {
                fontSize = Double.parseDouble(fontSizeStr);
            }
        } catch (NumberFormatException e) {
            fontSize = 1;
        }
        fs.setFontSize(fontSize);

        off--;
        if (off < 0) {
            return ctFont;
        }
        /*
         * 设置 字体粗细
         */
        int fontWeight = 400;
        // 解析font-weight
        // normal | bold | bolder | lighter | 100 | 200 | 300 | 400 | 500 | 600 | 700 | 800 | 900
        switch (arr[off].trim().toLowerCase()) {
            case "lighter":
            case "100":
                fontWeight = 100;
                off--;
                break;
            case "200":
                fontWeight = 200;
                off--;
                break;
            case "300":
                fontWeight = 300;
                off--;
                break;
            case "normal":
            case "400":
                fontWeight = 400;
                off--;
                break;
            case "500":
                fontWeight = 500;
                off--;
                break;
            case "600":
                fontWeight = 600;
                off--;
                break;
            case "bold":
            case "700":
                fontWeight = 700;
                off--;
                break;
            case "800":
                fontWeight = 800;
                off--;
                break;
            case "bolder":
            case "900":
                fontWeight = 900;
                off--;
                break;
            default:
                // 非字体宽度配置，忽略
        }
        fs.setFontWeight(fontWeight);
        if (off < 0) {
            return ctFont;
        }
        /*
         * 设置 是否斜体
         */
        // 解析 font-style: normal | italic
        switch (arr[off].trim()) {
            case "italic":
                fs.setItalic(true);
                break;
            case "normal":
            default:
                fs.setItalic(false);
                // 非字体样式配置，忽略
        }

        return ctFont;
    }

/**
     * 分析字间距偏移量并计算文字宽度
     *
     * @param text        文本
     * @param fontSetting 文字设置
     * @return 测量结果
     */
public static MeasureBody measureWithWith(String text, FontSetting fontSetting) {
        MeasureBody body = new MeasureBody();

        if (text.length() == 0) {
            return body;
        }

        int readDirection = fontSetting.getReadDirection();
        int charDirection = fontSetting.getCharDirection();

        char firstChar = text.charAt(0);
        char lastChar = text.charAt(text.length() - 1);

        final Double fontSize = fontSetting.getFontSize();
        if (readDirection == 0) {
            if (charDirection == 0) {
                body.offset = offset(text, fontSetting, 0, "W", 1);
                body.with(fontSetting.charWidth(lastChar));
            } else if (charDirection == 180) {
                body.offset = offset(text, fontSetting, 1, "W", 1);
                body.with(fontSetting.charWidth(firstChar));
                body.firstCharOffsetX = fontSetting.charWidth(firstChar);
                body.firstCharOffsetY = -fontSize;
            } else if (charDirection == 90 || charDirection == 270) {
                body.offset = offset(text, fontSetting, 0, "H", 1);
                body.with(fontSize);
                if (charDirection == 90) {
                    body.firstCharOffsetY = -fontSize;
                } else {
                    body.firstCharOffsetX = fontSize;
                }
            }
        } else if (readDirection == 180) {
            if (charDirection == 0) {
                body.offset = offset(text, fontSetting, 1, "W", -1);
                body.with(fontSetting.charWidth(firstChar));
                body.firstCharOffsetX = -fontSetting.charWidth(firstChar);
            } else if (charDirection == 180) {
                body.offset = offset(text, fontSetting, 0, "W", -1);
                body.with(fontSetting.charWidth(lastChar));
                body.firstCharOffsetY = -fontSize;
            } else if (charDirection == 90 || charDirection == 270) {
                body.offset = offset(text, fontSetting, 0, "H", -1);
                body.with(fontSize);
                if (charDirection == 90) {
                    body.firstCharOffsetX = -fontSize;
                    body.firstCharOffsetY = -fontSize;
                }
            }
        } else if (readDirection == 90) {
            if (charDirection == 0 || charDirection == 180) {
                body.offset = offset(text, fontSetting, 0, "H", 1);
                body.with(fontSize);
                if (charDirection == 0) {
                    body.firstCharOffsetY = fontSize;
                } else {
                    body.firstCharOffsetX = fontSize;
                }
            } else if (charDirection == 90) {
                body.offset = offset(text, fontSetting, 0, "W", 1);
                body.with(fontSetting.charWidth(lastChar));
            } else if (charDirection == 270) {
                body.offset = offset(text, fontSetting, 1, "W", 1);
                body.with(fontSetting.charWidth(firstChar));
                body.firstCharOffsetX = fontSize;
                body.firstCharOffsetY = fontSetting.charWidth(firstChar);
            }
        } else if (readDirection == 270) {
            if (charDirection == 0 || charDirection == 180) {
                body.offset = offset(text, fontSetting, 0, "H", -1);
                body.with(fontSize);
                if (charDirection == 180) {
                    body.firstCharOffsetX = fontSize;
                    body.firstCharOffsetY = -fontSize;
                }
            } else if (charDirection == 90) {
                body.offset = offset(text, fontSetting, 1, "W", -1);
                body.with(fontSetting.charWidth(firstChar));
                body.firstCharOffsetY = -fontSetting.charWidth(firstChar);
            } else if (charDirection == 270) {
                body.offset = offset(text, fontSetting, 0, "W", -1);
                body.with(fontSetting.charWidth(lastChar));
                body.firstCharOffsetX = fontSize;
            }
        }
        return body;
    }

