            return new int[]{
                    Integer.parseInt(rgba[0].trim()),
                    Integer.parseInt(rgba[1].trim()),
                    Integer.parseInt(rgba[2].trim()),
                    (int) (255 * Double.parseDouble(rgba[3]))
            };
        }

        // 尝试解析 #xxxxxx 格式的颜色值
        try {
            Color c = Color.decode(hex);
            return new int[]{c.getRed(), c.getGreen(), c.getBlue()};
        } catch (Exception e) {
            // 无法解析时返回黑色
            return null;
        }
