            return new Rectangle2D.Double(0, 0, fontObj.getCharWidthScale(c) * fontSize, fontSize);
        }
        // 如果字体缓存为空，则加载字体
        if (awtFont == null) {
            // 尝试从字体中获取AWT字体对象
            awtFont = fontObj.getFontObj();
            if (awtFont == null) {
                // 尝试从环境变量中加载字体
                awtFont = EnvFont.getFont(fontObj.getName(), fontObj.getFamilyName());
