/**
     * 将虚拟页面中的元素转为OFD元素加入图层中
     *
     * @param pageLoc 页面xml绝对路径
     * @param to      图形元素将要写入到的页面图层
     * @param content 需要加入图层得到元素
     */
private void convert2Layer(ST_Loc pageLoc, CT_Layer to, List<Div> content) {
        // 处理页面中的元素为OFD的图元
        for (Div elem : content) {
            // 忽略占位符和对象
            if ((elem instanceof PageAreaFiller) || elem.isPlaceholder()) {
                continue;
            }
            // 处理每一个元素的基础盒式模型属性，背景边框等，并加入到图层中
            int objStart = this.maxUnitID.get();
            DivRender.render(to, elem, maxUnitID);
            // 获取处理器，进行元素的渲染，扩展元素渲染器时，需要注册处理器
            Processor processor = registeredProcessor.get(elem.elementType());
            if (processor != null) {
                processor.render(pageLoc, to, resManager, elem, maxUnitID);
            }
            int objEnd = this.maxUnitID.get();
            // 调用元素渲染结束处理器，处理元素绘制完成后的逻辑
            ElementRenderFinishHandler onRenderFinish = elem.getOnRenderFinish();
            if (onRenderFinish != null) {
                ArrayList<ST_ID> objIds = new ArrayList<>(objEnd - objStart);
                ArrayList<ST_ID> resIds = new ArrayList<>();
                ArrayList<ST_ID> newResIds = resManager.getNewResIds();

                // 获取所有新的元素ID，判断是否是资源对象，若是资源对象则加入资源列表
                for (int id = objEnd; id > objStart; id--) {
                    ST_ID objId = new ST_ID(id);
                    if (newResIds.contains(objId)) {
                        resIds.add(objId);
                    } else {
                        objIds.add(objId);
                    }
                }
                onRenderFinish.handle(pageLoc, objIds, resIds);
            }
        }
    }

/**
     * 执行Div元素渲染
     *
     * @param pageLoc   页面在虚拟容器中绝对路径。
     * @param layer     图层
     * @param resManager 资源管理器
     * @param e         元素
     * @param maxUnitID 最大ID
     * @throws RenderException 渲染发生错误
     */
@Override
    public void render(ST_Loc pageLoc, CT_PageBlock layer, ResManager resManager, Div e, AtomicInteger maxUnitID) throws RenderException{
        render(layer, e, maxUnitID);
    }

