     *
     * @return 文档对象
     * @throws DocumentException     文档解析异常
     * @throws FileNotFoundException Document.xml文档不存在
     */
    public Document cdDefaultDoc() throws DocumentException, FileNotFoundException {
        return cdDoc(0);
    }

